const STORAGE_KEY='TaiwanBioTopoMaps.language';
export const normalizeLanguage=value=>value==='en'?'en':'zh-Hant';
export function readLanguage(storage){try{return normalizeLanguage((storage??globalThis.localStorage)?.getItem(STORAGE_KEY));}catch{return 'zh-Hant';}}
let language='zh-Hant';
export const getLanguage=()=>language;
export function setLanguage(value,storage){language=normalizeLanguage(value);try{(storage??globalThis.localStorage)?.setItem(STORAGE_KEY,language);}catch{}return language;}
export function tx(key,values={},lang=language){const pair=MESSAGES[key];if(!pair)throw Error('Unknown translation key: '+key);return pair[lang==='en'?1:0].replace(/\{(\w+)\}/g,(_,name)=>String(values[name]??''));}
export function t(text,lang=language){text=String(text);if(lang!=='en')return text;if(Object.hasOwn(TEXT,text))return TEXT[text];let m;
 if((m=text.match(/^第 (\d+) 列欄位數與標題不同；含逗號的文字需加雙引號。$/)))return `Row ${m[1]} has a different number of fields. Quote text containing commas.`;
 if((m=text.match(/^圖檔為 (\d+) × (\d+) px，請降低匯出寬度後再試。$/)))return `The image is ${m[1]} × ${m[2]} px. Reduce the export width and retry.`;
 if((m=text.match(/^海拔 (\d+)\/(\d+) · DEM z(\d+)(（依範圍調整）)?(?: · (\d+) 張載入失敗)?$/)))return `Elevation ${m[1]}/${m[2]} · DEM z${m[3]}${m[4]?' (adjusted to extent)':''}${m[5]?` · ${m[5]} failed`:''}`;
 return text;
}
const originalText=new WeakMap(),originalAttrs=new WeakMap();
const ignored='#groupList,#tableHead,#tableBody,#tooltip,#fileLabel,#lonCol,#latCol,#groupCol,script,style';
export function applyLanguage(root=document){
 const doc=root.ownerDocument||root;doc.documentElement.lang=language;
 const walker=doc.createTreeWalker(root.body||root,4);let node;
 while((node=walker.nextNode())){if(node.parentElement?.closest(ignored))continue;const raw=originalText.get(node)??node.nodeValue,trim=raw.trim();if(!originalText.has(node))originalText.set(node,raw);if(Object.hasOwn(TEXT,trim))node.nodeValue=raw.replace(trim,t(trim));}
 for(const el of root.querySelectorAll('[aria-label],[title]')){if(el.closest(ignored))continue;let attrs=originalAttrs.get(el);if(!attrs){attrs={};for(const key of ['aria-label','title'])if(el.hasAttribute(key))attrs[key]=el.getAttribute(key);originalAttrs.set(el,attrs);}for(const [key,value] of Object.entries(attrs))el.setAttribute(key,t(value));}
 doc.title=t('TaiwanBioTopoMaps｜互動製圖');const description=doc.querySelector('meta[name=description]');if(description)description.content=language==='en'?'Upload CSV records, map Taiwan biodiversity on terrain, and export PNG, SVG or PDF.':'上傳 CSV，互動製作臺灣與離島的海拔底圖、物種分布與共域圓餅，匯出 PNG、SVG、PDF。';const button=doc.getElementById('languageBtn');if(button){button.textContent=language==='en'?'中文':'EN';button.setAttribute('aria-label',language==='en'?'切換為繁體中文':'Switch to English');button.title=language==='en'?'繁體中文':'English';button.setAttribute('aria-pressed',String(language==='en'));}
}
